# Typed Result union with exhaustive PEP 634 match & boundary translation (Python 3.10+)
from dataclasses import dataclass
from typing import Generic, TypeVar

T, E = TypeVar('T'), TypeVar('E')
@dataclass(frozen=True) class Ok(Generic[T]): value: T
@dataclass(frozen=True) class Err(Generic[E]): error: E
Result = Ok[T] | Err[E]

@dataclass(frozen=True) class Declined: reason: str
@dataclass(frozen=True) class TransientFailure: retry_after_ms: int

def handle_capture(res: Result[str, Declined | TransientFailure]) -> int:
    match res:
        case Ok(tx_id): return 200
        case Err(Declined()): return 402
        case Err(TransientFailure()): return 503
